#include <stdio.h>
#include <string.h>

int main(void) {
    char message[16] = "Data";
    const char *suffix = " C";
    size_t used = strlen(message);
    size_t extra = strlen(suffix);
    if (extra >= sizeof message - used) return 1;
    strcat(message, suffix);
    printf("text=%s length=%zu capacity=%zu\n", message, strlen(message), sizeof message);
    printf("equal=%d\n", strcmp(message, "Data C") == 0);
    char overlap[] = "abcde";
    memmove(overlap, overlap + 1, strlen(overlap));
    printf("shifted=%s\n", overlap);
    return 0;
}

#include <stdio.h>
#include <string.h>

int main(void) {
    char line[16];
    if (fgets(line, sizeof line, stdin) == NULL) return 1;
    char *newline = strchr(line, '\n');
    if (newline != NULL) *newline = '\0';
    printf("First chunk: [%s], bytes=%zu\n", line, strlen(line));
    return 0;
}
